<script setup lang="ts">
import HelpHint from './HelpHint.vue'
import {computed} from 'vue'
import {type Field,type Section} from './api'
const props=defineProps<{modelValue:Section[],fields:Field[]}>()
const emit=defineEmits<{'update:modelValue':[Section[]],compose:[]}>()
const levels=[{label:'Scurt',value:'brief'},{label:'Standard',value:'standard'},{label:'Detaliat',value:'detailed'}]
const sections=computed(()=>props.modelValue)
function add(){emit('update:modelValue',[...sections.value,{id:'sectiune_'+Math.random().toString(36).slice(2,8),label:'Secțiune nouă',parent:'',condition_field:'',condition_value:'',repeatable:false,variants:[]}])}
function descendants(id:string,parent:string){let at=parent;const seen=new Set<string>();while(at&&!seen.has(at)){if(at===id)return true;seen.add(at);at=sections.value.find(s=>s.id===at)?.parent||''}return false}
function parents(id:string){return [{id:'',label:'Nivel principal'},...sections.value.filter(s=>s.id!==id&&!descendants(id,s.id))]}
function remove(id:string){if(props.fields.some(f=>f.section===id)||sections.value.some(s=>s.parent===id))return;emit('update:modelValue',sections.value.filter(s=>s.id!==id))}
function variant(s:Section){s.variants??=[];s.variants.push({id:'varianta_'+Math.random().toString(36).slice(2,8),label:'Formulare nouă',detail:'standard',condition_field:props.fields.find(f=>f.section===s.id)?.key||props.fields[0]?.key||'',condition_value:'',text:'',required_fields:[]})}
function insertField(s:Section,index:number,key:string){const v=s.variants?.[index];if(v)v.text+='{{'+key+'}}'}
</script>
<template><section class="paper section-designer"><div class="section-heading"><div><h2>Secțiuni și variante de redactare<HelpHint topic="sections"/></h2><p class="muted small">O secțiune poate reprezenta orice: simptome, ficat, ventricul stâng sau recomandări. Subsecțiunile pot avea propriile variante.</p></div><Button label="Adaugă secțiune" icon="pi pi-plus" @click="add"/></div>
<p v-if="!sections.length" class="muted">Adaugă prima secțiune și asociază-i câmpurile din editor.</p>
<details v-for="s in sections" :key="s.id" class="section-card"><summary>{{s.parent?'↳ ':''}}{{s.label}} <small>· {{s.variants?.length||0}} variante</small></summary><div class="two"><label><span class="help-label">Denumirea secțiunii<HelpHint topic="sectionName"/></span><InputText v-model="s.label" maxlength="120"/></label><label><span class="help-label">În cadrul secțiunii<HelpHint topic="parent"/></span><Select v-model="s.parent" :options="parents(s.id)" optionValue="id" optionLabel="label"/></label><label><span class="help-label">Nivel de detaliu implicit<HelpHint topic="detail"/></span><Select v-model="s.detail" :options="[{label:'Din șablon',value:''},...levels]" optionLabel="label" optionValue="value"/></label><label><span class="help-label">Arată secțiunea numai când câmpul<HelpHint topic="sectionCondition"/></span><Select v-model="s.condition_field" :options="[{key:'',label:'Întotdeauna'},...fields]" optionLabel="label" optionValue="key"/></label></div><label v-if="s.condition_field"><span class="help-label">Are valoarea exactă<HelpHint topic="conditionValue"/></span><InputText v-model="s.condition_value"/></label>
<label><span class="help-label">Dicționarul structurii pentru dictare și redactare<HelpHint topic="sectionVocabulary"/></span><Textarea :modelValue="s.speech_terms?.join('\n')||''" @update:modelValue="s.speech_terms=($event||'').split('\n').map(x=>x.trim()).filter(Boolean)" rows="4" :aria-label="'Dicționar: '+s.label" placeholder="Un termen sau o expresie pe rând"/><span class="muted small">Maximum 64 de expresii și 2.048 de octeți pe secțiune. Publică versiunea pentru activare.</span></label>
<label class="check"><input type="checkbox" v-model="s.hide_when_empty"/> <span class="help-label">Ascunde secțiunea dacă nu există date documentate<HelpHint topic="hideEmpty"/></span></label><p class="muted small">Câmpuri asociate: {{fields.filter(f=>f.section===s.id).map(f=>f.label).join(', ')||'Niciun câmp încă — asociază-le din lista de câmpuri.'}}</p>
<details v-for="(v,index) in s.variants" :key="v.id" class="variant-card"><summary>{{v.label}} · {{levels.find(l=>l.value===v.detail)?.label}}</summary><div class="two"><label><span class="help-label">Denumirea variantei<HelpHint topic="variantName"/></span><InputText v-model="v.label" maxlength="120"/></label><label><span class="help-label">Nivel de detaliu<HelpHint topic="variantDetail"/></span><Select v-model="v.detail" :options="levels" optionLabel="label" optionValue="value"/></label><label><span class="help-label">Se aplică dacă acest câmp<HelpHint topic="variantField"/></span><Select v-model="v.condition_field" :options="fields" optionLabel="label" optionValue="key"/></label><label><span class="help-label">Regulă de aplicare<HelpHint topic="operator"/></span><Select v-model="v.condition_operator" :options="[{label:'Valoare exactă',value:'equals'},{label:'Câmp documentat explicit',value:'documented'}]" optionLabel="label" optionValue="value"/></label><label v-if="v.condition_operator!=='documented'"><span class="help-label">Conține valoarea documentată exactă<HelpHint topic="variantValue"/></span><InputText v-model="v.condition_value" maxlength="500" placeholder="De exemplu: normal, numai dacă este documentat"/></label></div><label><span class="help-label">Formularea medicului<HelpHint topic="wording"/></span><Textarea v-model="v.text" rows="4" maxlength="8000" placeholder="Scrie formularea și inserează câmpurile necesare."/></label><div class="actions"><Button v-for="f in fields.filter(f=>f.section===s.id)" :key="f.key" :label="'+ '+f.label" text size="small" @click="insertField(s,index,f.key)"/><Button label="Elimină varianta" text severity="danger" @click="s.variants?.splice(index,1)"/></div><p class="muted small">Varianta cere dovezi pentru condiție și pentru fiecare câmp inserat. Fără date suficiente, se păstrează formularea de bază. Două variante simultan potrivite sunt semnalate pentru revizuire.</p></details>
<div class="actions"><Button label="Adaugă variantă" size="small" severity="secondary" @click="variant(s)" :disabled="!fields.length"/><HelpHint topic="variantActions"/><Button label="Elimină secțiunea" text severity="danger" @click="remove(s.id)" :disabled="fields.some(f=>f.section===s.id)||sections.some(child=>child.parent===s.id)"/><HelpHint topic="removeSection"/></div></details>
<Button v-if="sections.length" label="Generează structura în document" icon="pi pi-file-edit" severity="secondary" @click="emit('compose')"/><HelpHint v-if="sections.length" topic="compose"/><p v-if="sections.length" class="muted small">Înlocuiește conținutul editorului cu structura secțiunilor și câmpurile asociate. Variantele se aplică ulterior, pe baza dictării și a nivelului de detaliu ales.</p></section></template>
